"""Real JEE Main questions — Chemistry Unit 7: Redox Reactions & Electrochemistry. Our own solutions; chk re-solves
the numerical ones (Nernst, ΔG = −nFE, Faraday's laws, Kohlrausch). Skipped: items whose official key we could not
reproduce or that were ambiguous (lead-battery 'anode on charging', the H2/AgCl cell choice, the 338-or-339 log K,
a 45.75 decimal answer, the 'number of conductors' list) and items that belong to the d-block / p-block units."""
import math
from common import new_registry, pick, near, verify
P, add = new_registry()
F_ = 96500
def bis(f, lo, hi, n=300):
    flo = f(lo)
    for _ in range(n):
        m = (lo + hi) / 2
        if (f(m) > 0) == (flo > 0): lo = m
        else: hi = m
    return (lo + hi) / 2
S4a = ['Statement I is true but Statement II is false', 'Both Statement I and Statement II are false', 'Both Statement I and Statement II are true', 'Statement I is false but Statement II is true']
S4b = ['Both Statement I and Statement II are correct', 'Statement I is incorrect but Statement II is correct', 'Statement I is correct but Statement II is incorrect', 'Both Statement I and Statement II are incorrect']
S4c = ['Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Both Statement I and Statement II are correct', 'Statement I is incorrect but Statement II is correct']
S4d = ['Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
S4e = ['Statement I is correct but statement II is incorrect', 'Statement I is incorrect but statement II is correct', 'Both statement I and statement II are incorrect', 'Both statement I and statement II are correct']

